import MessageSender = chrome.runtime.MessageSender;

let _otherTabsDataCache = new Map<string, string>();

export function addToOtherTabsDataCache(data: string) {
    let id = Date.now().toString();
    _otherTabsDataCache.set(id, data);
    return id as DataCacheId;
}

function copyFullTable(table: HTMLTableElement) {
    let headerCells = table.tHead!.children[0].children as HTMLCollectionOf<HTMLTableCellElement>;
    let headers = [...headerCells].filter(cell => cell.style.display !== "none").map(cell => cell.innerText);
    let rows = table.tBodies[0].children as HTMLCollectionOf<HTMLTableRowElement>;
    let cells = [...rows].map(row => [...row.cells].filter(cell => cell.style.display !== "none").map(cell => cell.innerText));
    createAndCopyTable(headers, cells);
}

function copyOneColumn(table: HTMLTableElement, index: number) {
    createAndCopyTable(
        [(table.tHead!.children[0].children[index] as HTMLTableCellElement).innerText],
        [...table.tBodies[0].rows].map(row => [row.cells[index].innerText])
    );
}

function createAndCopyTable(headers: Iterable<string>, cols: Iterable<Iterable<string>>) {
    navigator.clipboard.writeText(createHtmlTable(headers, cols).outerHTML).then(_r => {});
}

function reSortTableByColumn(ev: MouseEvent, table: HTMLTableElement, fetchFirst: boolean, valueFuncs: ColumnValueFunc[]) {
    let header = table.tHead!.children[0].children[getColumnIndex(ev)];
    let wasAscending = header.classList.contains("sortAscending");
    if(fetchFirst)
        forTableDo(ev, (_fetchedTable, index) => sortTableByColumn(table, index, wasAscending, valueFuncs[index]));
    else {
        let columnIndex = getColumnIndex(ev);
        sortTableByColumn(table, columnIndex, wasAscending, valueFuncs[columnIndex]);
    }
}

export function decorateTableHeader(table: HTMLTableElement, fetchFullTable: boolean) {
    if (table.tHead!.classList.contains("clickHandler"))
        return;
    table.tHead!.classList.add("clickHandler");
    if(!options.showTableHeaders)
        return;

    let valueFuncs = getDefaultValueFuncs(table);
    Array.from(table.tHead!.children[0].children)
        .forEach((colHeader: Element) => {
            (colHeader as HTMLElement).onclick = (ev) => {
                reSortTableByColumn(ev, table, fetchFullTable, valueFuncs);
            };
            if(table.classList.contains(def.NO_MENU))
                return;
            let {first: span, last: idiom} = emmet.appendChild((colHeader as HTMLElement), 'span>button.miniButton.naked>i.fas.fa-list');
            let menu = new DropDownMenu(span as HTMLElement, idiom!.parentElement!);
            menu.addItem("Toon unieke waarden", 0, (ev) => { forTableDo(ev, showDistinctColumn); });
            menu.addItem("Verberg kolom", 0, (ev) => { console.log("verberg kolom"); forTableColumnDo(ev, hideColumn)});
            menu.addItem("Toon alle kolommen", 0, (ev) => { console.log("verberg kolom"); forTableColumnDo(ev, showColumns)});
            menu.addSeparator("Sorteer", 0);
            menu.addItem("Laag naar hoog (a > z)", 1, (ev) => { forTableDo(ev, (tableMeta, index) => sortTableByColumn(table, index, false, valueFuncs[index]))});
            menu.addItem("Hoog naar laag (z > a)", 1, (ev) => { forTableDo(ev, (tableMeta, index) => sortTableByColumn(table, index, true, valueFuncs[index]))});
            menu.addSeparator("Sorteer als:", 1);
            menu.addItem("Tekst", 2, (_ev) => { });
            menu.addItem("Getallen", 2, (_ev) => { });
            menu.addSeparator("Kopieer nr klipbord", 0);
            menu.addItem("Kolom", 1, (ev) => { forTableDo(ev, (tableMeta, index) => copyOneColumn(table, index))});
            menu.addItem("Hele tabel", 1, (ev) => { forTableDo(ev, (tableMeta, _index) => copyFullTable(table))});
            menu.addSeparator("<= Samenvoegen", 0);
            menu.addItem("met spatie", 1, (ev) => { forTableColumnDo(ev, createTwoColumnsCmd(Direction.LEFT, mergeColumnWithSpace))});
            menu.addItem("met comma", 1, (ev) => { forTableColumnDo(ev, createTwoColumnsCmd(Direction.LEFT, mergeColumnWithComma))});
            menu.addSeparator("Verplaatsen", 0);
            menu.addItem("<=", 1, (ev) => { forTableColumnDo(ev, createTwoColumnsCmd(Direction.LEFT, swapColumns))});
            menu.addItem("=>", 1, (ev) => { forTableColumnDo(ev, createTwoColumnsCmd(Direction.RIGHT, swapColumns))});
        });
    relabelHeaders(table.tHead!.children[0] as HTMLTableRowElement);
}

function getDistinctColumn(tableContainer: HTMLElement, index: number) {
    let rows = Array.from(tableContainer.querySelector("tbody")!.rows);

    return distinct(rows.map(row => row.children[index].textContent)).sort();
}

